/**
 * OG fonts, subset and base64-inlined.
 *
 * The OG routes run on the edge runtime, because @vercel/og's Node build
 * calls fileURLToPath on a Windows path and throws Invalid URL — the build
 * fails locally on every card. Edge avoids that code path entirely, but it
 * has no fs, so the faces are inlined here rather than read from disk.
 *
 * They are SUBSET to the glyphs a card can actually use. Inlined whole,
 * four faces plus four photos put the Founder Note's edge function at
 * 1.07MB against a 1MB plan limit and the production deploy failed — the
 * fonts were carrying Cyrillic, Greek and Vietnamese for a card that sets
 * one English headline. Add a character outside the set below and it will
 * render as a blank box, so widen the set rather than guessing.
 */

const b64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0)).buffer;

export const playfair500 = b64(
  '',
);

export const playfair500Italic = b64(
  '',
);

export const inter400 = b64(
  '',
);

export const jetbrains700 = b64(
  '',
);
